package com.adib.maintenance;
import android.app.Activity;import android.graphics.Color;import android.graphics.Typeface;import android.view.*;import android.widget.*;import org.json.*;
/** Reparents existing editor controls: no duplicate values or save handlers. */
final class TaskDetailTabs extends LinearLayout {
 final LinearLayout properties,description,discussion,children;private final FrameLayout content;private final TextView heading;private final TextView[] tabs=new TextView[4];private final View[] pages=new View[4];private final boolean dark;private final int blue=HybridUi.BLUE,fg,bg;private Runnable childrenRefresh;private ScrollView workScroll;private LinearLayout workMain;private View workNav;private Button workBack;private Runnable workRefresh;
 TaskDetailTabs(Activity a,LinearLayout form,EditText title,View descriptionField,View photos,LinearLayout comments,boolean dark,String source){super(a);this.dark=dark;fg=HybridUi.text(dark);bg=HybridUi.surface(dark);setOrientation(VERTICAL);setBackgroundColor(bg);setTag("task-detail-tabs");LinearLayout head=new LinearLayout(a);head.setGravity(Gravity.CENTER_VERTICAL);head.setPadding(dp(12),dp(10),dp(12),dp(10));heading=label(title.getText().toString(),19,true);head.addView(heading,new LayoutParams(0,-2,1));addView(head);TextView context=label(source,11,false);context.setPadding(dp(12),0,dp(12),dp(8));context.setTextColor(HybridUi.muted(dark));addView(context);title.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int af){}public void onTextChanged(CharSequence s,int st,int b,int c){heading.setText(s.length()==0?"Adsız":s);}public void afterTextChanged(android.text.Editable e){}});
 LinearLayout nav=new LinearLayout(a);nav.setTag("task-tab-strip");nav.setGravity(Gravity.CENTER);String[] names={"Söhbət","Tapşırıq","Təsvir","Alt tapşırıqlar"};for(int i=0;i<4;i++){final int index=i;TextView tab=new TextView(a);tab.setGravity(Gravity.CENTER);tab.setAllCaps(false);tab.setText(names[i]);tab.setTextSize(12);tab.setMaxLines(1);tab.setHorizontallyScrolling(false);tab.setMinWidth(dp(68));tab.setMinimumWidth(dp(68));tab.setPadding(dp(8),0,dp(8),0);tab.setBackgroundColor(Color.TRANSPARENT);tab.setTag("task-tab:"+i);tab.setContentDescription(names[i]);nav.addView(tab,new LayoutParams(0,dp(48),1));tab.setOnClickListener(v->select(index));tabs[i]=tab;}addView(nav,new LayoutParams(-1,dp(48)));View line=new View(a);line.setBackgroundColor(HybridUi.border(dark));addView(line,new LayoutParams(-1,dp(1)));content=new FrameLayout(a);addView(content,new LayoutParams(-1,0,1));properties=form;description=new LinearLayout(a);discussion=comments;children=new LinearLayout(a);for(LinearLayout page:new LinearLayout[]{description,children}){page.setOrientation(VERTICAL);page.setPadding(dp(16),dp(12),dp(16),dp(12));}moveField(form,description,descriptionField);if(photos!=null&&photos.getParent() instanceof ViewGroup){((ViewGroup)photos.getParent()).removeView(photos);description.addView(photos);}if(comments.getParent() instanceof ViewGroup)((ViewGroup)comments.getParent()).removeView(comments);comments.setPadding(dp(12),dp(8),dp(12),dp(12));LinearLayout[] bodies={discussion,properties,description,children};for(int i=0;i<4;i++){ScrollView scroll=new ScrollView(a);scroll.setFillViewport(true);scroll.addView(bodies[i]);scroll.setTag("task-pane:"+i);content.addView(scroll,new FrameLayout.LayoutParams(-1,-1));pages[i]=scroll;}select(1);
 }
 @Override protected void onMeasure(int widthSpec,int heightSpec){int available=View.MeasureSpec.getSize(widthSpec)/4-dp(16);float base=12*getResources().getDisplayMetrics().scaledDensity;for(TextView tab:tabs){if(tab==null)continue;android.graphics.Paint paint=new android.graphics.Paint(tab.getPaint());paint.setTextSize(base);float width=paint.measureText(tab.getText().toString());float size=Math.max(dp(10),Math.min(base,base*Math.max(dp(32),available)/Math.max(1,width)));if(Math.abs(tab.getTextSize()-size)>.1f)tab.setTextSize(android.util.TypedValue.COMPLEX_UNIT_PX,size);}super.onMeasure(widthSpec,heightSpec);}
 private void moveField(LinearLayout from,LinearLayout to,View field){if(field==null)return;View top=field;while(top.getParent() instanceof View&&top.getParent()!=from)top=(View)top.getParent();if(top.getParent()!=from)return;int index=from.indexOfChild(top);if(index>0&&from.getChildAt(index-1) instanceof TextView&&!(from.getChildAt(index-1) instanceof EditText)){View label=from.getChildAt(index-1);from.removeView(label);to.addView(label);}from.removeView(top);to.addView(top);if(field instanceof EditText){HybridUi.edit((EditText)field,dark,true);field.setMinimumHeight(dp(160));((EditText)field).setGravity(Gravity.TOP);}}
 void select(int index){if(workScroll!=null){if(index==3){showWork();return;}workScroll.setVisibility(GONE);workNav.setVisibility(VISIBLE);workBack.setVisibility(VISIBLE);}for(int i=0;i<4;i++){pages[i].setVisibility(i==index?VISIBLE:GONE);tabs[i].setTextColor(i==index?blue:fg);tabs[i].setTypeface(null,i==index?Typeface.BOLD:Typeface.NORMAL);tabs[i].setSelected(i==index);final boolean active=i==index;tabs[i].setBackground(new android.graphics.drawable.Drawable(){public void draw(android.graphics.Canvas c){if(active){android.graphics.Paint paint=new android.graphics.Paint();paint.setColor(blue);android.graphics.Rect b=getBounds();c.drawRect(b.left,b.bottom-dp(3),b.right,b.bottom,paint);}}public void setAlpha(int value){}public void setColorFilter(android.graphics.ColorFilter filter){}public int getOpacity(){return android.graphics.PixelFormat.TRANSLUCENT;}});tabs[i].setPadding(dp(8),0,dp(8),0);}tabs[index].post(()->tabs[index].requestRectangleOnScreen(new android.graphics.Rect(0,0,tabs[index].getWidth(),tabs[index].getHeight()),true));if(index==3&&childrenRefresh!=null)childrenRefresh.run();}

 void workScreen(Activity activity,org.json.JSONObject task,Spinner status,Spinner priority,EditText estimate,EditText date,EditText employee,View timer,EditText notes,Runnable complete){
 setBackgroundColor(HybridUi.bg(dark));heading.setTextSize(24);LinearLayout nav=(LinearLayout)findViewWithTag("task-tab-strip");workNav=nav;workBack=new Button(activity);HybridUi.button(workBack,dark,false);workBack.setText("← İş ekranına");workBack.setTag("work-screen-back");workBack.setOnClickListener(v->showWork());addView(workBack,new LayoutParams(-1,dp(44)));workBack.setVisibility(GONE);
 workScroll=new ScrollView(activity);workScroll.setFillViewport(true);workScroll.setTag("task-work-screen");workMain=new LinearLayout(activity);workMain.setOrientation(VERTICAL);workMain.setPadding(dp(16),dp(8),dp(16),dp(24));workScroll.addView(workMain);content.addView(workScroll,new FrameLayout.LayoutParams(-1,-1));
 TextView meta=label("",14,false);meta.setTextColor(HybridUi.muted(dark));meta.setPadding(0,dp(8),0,dp(12));meta.setTag("work-task-meta");workMain.addView(meta);Runnable updateMeta=()->{String who=employee==null?task.optString("assigneeName",""):employee.getText().toString();String due=date==null?CompactDesign.date(task):date.getText().toString();try{org.json.JSONObject value=new org.json.JSONObject().put("date",due);due=CompactDesign.date(value);}catch(Exception ignored){}meta.setText((who.isEmpty()?"Məsul şəxs seçilməyib":who)+(due.isEmpty()?"":" · "+due));};updateMeta.run();android.text.TextWatcher metadataWatch=new android.text.TextWatcher(){public void beforeTextChanged(CharSequence x,int st,int c,int after){}public void onTextChanged(CharSequence x,int st,int before,int count){updateMeta.run();}public void afterTextChanged(android.text.Editable x){}};if(date!=null)date.addTextChangedListener(metadataWatch);if(employee!=null)employee.addTextChangedListener(metadataWatch);
 LinearLayout workBox=new LinearLayout(activity);workBox.setOrientation(VERTICAL);workBox.setPadding(dp(12),dp(10),dp(12),dp(12));workBox.setBackground(HybridUi.rounded(HybridUi.surface(dark),dp(12),HybridUi.border(dark),dp(1)));workBox.setTag("work-actions-card");workMain.addView(workBox,new LayoutParams(-1,-2));TextView summary=label("",15,true);summary.setPadding(0,0,0,dp(8));workBox.addView(summary);Runnable paint=()->summary.setText((status==null?task.optString("status",""):AzLocale.label(String.valueOf(status.getSelectedItem())))+(priority==null?"":" · "+String.valueOf(priority.getSelectedItem())));paint.run();workRefresh=paint;meta.setOnClickListener(v->select(1));summary.setOnClickListener(v->select(1));
 TextView plan=label("",16,false);plan.setPadding(0,dp(4),0,dp(10));workBox.addView(plan);Runnable updatePlan=()->{String value=estimate==null?"":estimate.getText().toString().trim();try{plan.setText(value.isEmpty()?"Təxmini vaxt seçilməyib":WorkTimerClient.timeLabel(Double.parseDouble(value))+" planlaşdırılıb");}catch(Exception ignored){plan.setText("Təxmini vaxtı yoxlayın");}};updatePlan.run();if(estimate!=null)estimate.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence x,int st,int c,int after){}public void onTextChanged(CharSequence x,int st,int before,int count){updatePlan.run();}public void afterTextChanged(android.text.Editable x){}});
 if(timer!=null){if(timer.getParent() instanceof ViewGroup)((ViewGroup)timer.getParent()).removeView(timer);workBox.addView(timer,new LayoutParams(-1,-2));}
 TextView desc=label("",16,false);desc.setPadding(0,dp(10),0,dp(8));desc.setTag("work-description-preview");Runnable updateNotes=()->{String value=notes==null?"":notes.getText().toString();desc.setText(value.isEmpty()?"Təsvir əlavə edin":value.length()>220?value.substring(0,220)+"…":value);};updateNotes.run();if(notes!=null)notes.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence x,int st,int c,int after){}public void onTextChanged(CharSequence x,int st,int before,int count){updateNotes.run();}public void afterTextChanged(android.text.Editable x){}});TextView title=label("İndi nə etmək lazımdır?",16,true);title.setPadding(0,dp(20),0,0);workMain.addView(title);workMain.addView(desc);Button detail=new Button(activity);HybridUi.button(detail,dark,false);detail.setText("Şəkillər, nəticə və təsvir  ›");detail.setOnClickListener(v->select(2));workMain.addView(detail,new LayoutParams(-1,dp(48)));
 if(children.getParent() instanceof ViewGroup)((ViewGroup)children.getParent()).removeView(children);workMain.addView(children,new LayoutParams(-1,-2));Button props=new Button(activity);HybridUi.button(props,dark,false);props.setTag("work-all-properties");props.setText("Bütün xüsusiyyətlər  ›");props.setOnClickListener(v->{paint.run();select(1);});workMain.addView(props,new LayoutParams(-1,dp(48)));
 LinearLayout actions=new LinearLayout(activity);actions.setPadding(0,dp(12),0,0);Button done=new Button(activity);HybridUi.button(done,dark,true);done.setText("Tamamla");done.setTag("work-task-complete");done.setOnClickListener(v->complete.run());actions.addView(done,new LayoutParams(0,dp(48),1));Button chat=new Button(activity);HybridUi.button(chat,dark,false);chat.setText("Müzakirə");chat.setOnClickListener(v->select(0));LayoutParams cp=new LayoutParams(0,dp(48),1);cp.leftMargin=dp(8);actions.addView(chat,cp);addView(actions,new LayoutParams(-1,-2));done.setEnabled(!task.optBoolean("completed"));showWork();
 }
 void showWork(){if(workScroll==null)return;if(workRefresh!=null)workRefresh.run();for(View page:pages)page.setVisibility(GONE);workNav.setVisibility(GONE);workBack.setVisibility(GONE);workScroll.setVisibility(VISIBLE);if(childrenRefresh!=null)childrenRefresh.run();}
 void setSubtaskCount(int count){int n=Math.max(0,count);tabs[3].setText(n>0?"Alt tapşırıqlar · "+n:"Alt tapşırıqlar");tabs[3].setContentDescription(n>0?"Alt tapşırıqlar: "+n:"Alt tapşırıqlar: yox");requestLayout();}
 void setChildren(Runnable refresh){childrenRefresh=refresh;refresh.run();}
 TextView label(String text,int size,boolean bold){TextView v=new TextView(getContext());v.setText(text);v.setTextSize(size);v.setTextColor(fg);if(bold)v.setTypeface(null,Typeface.BOLD);return v;}
 void message(String text){TextView v=label(text,13,false);v.setPadding(0,dp(12),0,dp(12));children.addView(v);}
 int dp(int x){return (int)(getResources().getDisplayMetrics().density*x+.5f);}
}
